'use strict';

// MODULES //

var vm = require( 'vm' );
var dirname = require( 'path' ).dirname;
var replace = require( '@stdlib/string/replace' );
var pkg2alias = require( '@stdlib/namespace/pkg2alias' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var tryRequire = require( '@stdlib/utils/try-require' );
var compareValues = require( '@stdlib/_tools/doctest/compare-values' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var RE_EXTERNAL_ALIAS = /{{alias:([\s\S]+?)}}/g;
var RE_ASSIGNMENT = /(?:var|let|const)? ?([a-zA-Z0-9]*) *=/;


// MAIN //

/**
* Rule for enforcing that return annotation values mirror actual output.
*
* @param {Context} context - lint context
* @returns {Object} validators
*/
function main( context ) {
	/**
	* Checks whether return annotation values mirror actual output.
	*
	* @private
	* @param {Object} section - examples section
	*/
	function returnValues( section ) {
		var examples;
		var expected;
		var current;
		var pkgName;
		var actual;
		var match;
		var scope;
		var code;
		var msg;
		var pkg;
		var out;
		var key;
		var N;
		var o;
		var a;
		var b;
		var i;

		// FIXME: clean-up this logic

		if ( context.meta.filepath ) {
			expected = [];
			actual = [];
			pkg = dirname( dirname( context.meta.filepath ) );

			scope = {
				'setTimeout': setTimeout,
				'require': require
			};
			pkgName = pkg2alias( pkg ) || 'ALIAS';

			// TODO: use @stdlib/utils/deep-set once refactored!
			pkgName = pkgName.split( '.' );
			N = pkgName.length;
			o = scope;
			for ( i = 0; i < N; i++ ) {
				key = pkgName[ i ];
				if ( i < N-1 ) {
					if ( !hasOwnProp( o, key ) ) {
						o[ key ] = {};
					}
					o = o[ key ];
				} else {
					o[ key ] = require( pkg ); // eslint-disable-line stdlib/no-dynamic-require
				}
			}
			// TODO: process external aliases *BEFORE* creating the context (and also, what is going on here, given that the return value is ignored?)
			vm.createContext( scope );

			examples = section.examples;
			for ( i = 0; i < examples.length; i++ ) {
				current = examples[ i ];
				code = current.code;
				code = replace( code, '{{alias}}', pkgName.join( '.' ) );
				code = replace( code, RE_EXTERNAL_ALIAS, replaceAliases );
				try {
					out = vm.runInContext( code, scope );
					if ( current.output ) {
						expected.push( current.output );
						match = code.match( RE_ASSIGNMENT );
						if ( match && match[ 1 ] ) {
							actual.push( scope[ match[ 1 ] ] );
						} else {
							actual.push( out );
						}
					}
				} catch ( err ) {
					if ( current.output !== '<Error>' ) {
						// If the error was due to an unknown package identifier, strip the `require` stacktrace:
						msg = replace( err.message, /\nRequire stack:[\s\S]+/, '' );
						msg = format( 'Received an unexpected error when running example `%s`: %s', code, msg );
						context.report( msg, section );
					}
					break;
				}
			}
			for ( i = 0; i < expected.length; i++ ) {
				a = actual[ i ];
				b = expected[ i ];
				msg = compareValues( a, b );
				if ( msg ) {
					context.report( msg, section );
				}
			}
		}

		/**
		* Replaces aliases to other packages in REPL example code and registers the respective packages in the runtime context.
		*
		* @private
		* @param {string} match - full match
		* @param {string} pkg - package path
		* @returns {string} variable name
		*/
		function replaceAliases( match, pkg ) {
			var alias;
			var key;
			var len;
			var err;
			var o;
			var i;

			alias = pkg2alias( pkg );
			if ( alias === null ) {
				// Attempt to `require` the package, thus confirming that the package actually exists:
				err = tryRequire( pkg );

				// If an error was returned, we were unable to import the package...
				if ( err instanceof Error ) {
					// Return a string which will raise an exception:
					return format( 'require(\'%s\')', pkg );
				}
				// If an alias does not exist in the global namespace, dynamically `require` a package so that the desired expression can be executed:
				return format( '(require(\'%s\'))', pkg );
			}
			alias = alias.split( '.' );
			len = alias.length;

			// TODO: use @stdlib/utils/deep-set once refactored!
			o = scope;
			for ( i = 0; i < len; i++ ) {
				key = alias[ i ];
				if ( i < len-1 ) {
					if ( !hasOwnProp( o, key ) ) {
						o[ key ] = {};
					}
					o = o[ key ];
				} else {
					o[ key ] = require( pkg ); // eslint-disable-line stdlib/no-dynamic-require
				}
			}
			return alias.join( '.' );
		}
	}

	return {
		'examples': returnValues
	};
}


// EXPORTS //

module.exports = main;
